def run(case, finance):
    p=finance.get("reduced_plan") or finance["pathways"][0]
    cost=p["estimated_cost_pkr"]
    return {"Today":[{"action":"Complete priority observation/test before treatment","cost_pkr":min(cost,1000),"priority":"High","checkpoint":"Confirm evidence"}],"Next 7 Days":[{"action":"Apply only the confirmed, targeted action","cost_pkr":max(cost-1000,0),"priority":"High","checkpoint":"Check symptom progression"}],"Next 30 Days":[{"action":"Review crop response and records","cost_pkr":0,"priority":"Medium","checkpoint":"Re-evaluate if worsening"}],"Next Crop Stage":[{"action":"Review nutrition and protection needs using evidence","cost_pkr":0,"priority":"Medium","checkpoint":"Stage transition"}],"Harvest / End of Season":[{"action":"Record outcome, cost and unresolved issues","cost_pkr":0,"priority":"Medium","checkpoint":"Season review"}],"Next Season":[{"action":"Use prevention, clean/certified material where relevant, and baseline testing","cost_pkr":0,"priority":"Medium","checkpoint":"Before planting"}],"estimated_plan_cost_pkr":cost}
